BEGIN TRANSACTION READ ONLY;
SET LOCAL statement_timeout='5s';
SET LOCAL lock_timeout='500ms';
SET LOCAL application_name='ce1_ce100_probe_preflight';
SELECT jsonb_build_object(
 'captured_at',clock_timestamp(),
 'roles',(SELECT jsonb_agg(jsonb_build_object('role',r.rolname,'bypass_rls',r.rolbypassrls,'settings',(SELECT jsonb_agg(c) FROM unnest(r.rolconfig) c WHERE c ~ '^(statement_timeout|lock_timeout|pgrst.db_pre_request|pgrst.db_tx_end)='))) FROM pg_roles r WHERE r.rolname IN ('anon','authenticated','authenticator')),
 'database_role_settings',(SELECT coalesce(jsonb_agg(jsonb_build_object('role',coalesce(r.rolname,'all'),'database',coalesce(d.datname,'all'),'setting',c)),'[]'::jsonb) FROM pg_db_role_setting s LEFT JOIN pg_roles r ON r.oid=s.setrole LEFT JOIN pg_database d ON d.oid=s.setdatabase CROSS JOIN LATERAL unnest(s.setconfig)c WHERE c ~ '^(statement_timeout|lock_timeout|pgrst.db_pre_request|pgrst.db_tx_end)=' AND (d.datname=current_database() OR s.setdatabase=0) AND (r.rolname IN ('anon','authenticated','authenticator') OR s.setrole=0)),
 'relation',(SELECT jsonb_build_object('kind',c.relkind,'rls',c.relrowsecurity,'anon_select',has_table_privilege('anon',c.oid,'SELECT'),'authenticated_select',has_table_privilege('authenticated',c.oid,'SELECT')) FROM pg_class c WHERE c.oid='public.mercadona_products'::regclass),
 'policies',(SELECT jsonb_agg(jsonb_build_object('name',policyname,'roles',roles,'command',cmd,'qual',qual)) FROM pg_policies WHERE schemaname='public' AND tablename='mercadona_products'),
 'indexes',(SELECT jsonb_agg(jsonb_build_object('name',indexname,'definition',indexdef)) FROM pg_indexes WHERE schemaname='public' AND tablename='mercadona_products' AND indexdef ~ '(display_name_norm|id|published)'),
 'client_connections',(SELECT count(*) FROM pg_stat_activity WHERE backend_type='client backend' AND pid<>pg_backend_pid()),
 'blocked_clients',(SELECT count(*) FROM pg_stat_activity WHERE backend_type='client backend' AND cardinality(pg_blocking_pids(pid))>0 AND pid<>pg_backend_pid())
) AS evidence;
ROLLBACK;

BEGIN TRANSACTION READ ONLY;
SET LOCAL statement_timeout='5s';
SET LOCAL lock_timeout='500ms';
SET LOCAL ROLE anon;
EXPLAIN (FORMAT JSON)
SELECT id,display_name,display_name_ca,slug,packaging,thumbnail,unit_price,price_per_unit,price_per_unit_unit,category_name,category_id,display_name_norm
FROM public.mercadona_products
WHERE published=true AND (regions IS NULL OR regions='{}'::text[] OR regions @> ARRAY['Catalunya']::text[])
ORDER BY display_name_norm ASC NULLS LAST,id ASC
LIMIT 50;
ROLLBACK;
